from __future__ import annotations

import copy
import importlib
import json
import os
import sys
import tempfile
from pathlib import Path

# genlayer-test 0.30.0rc2 keeps fd 0 mapped to an injected temporary calldata
# file. Windows can report the file as busy during the loader's immediate
# cleanup; keep this shim scoped to autogenerated temp files.
if os.name == "nt":
    _unlink = os.unlink
    _temp_root = os.path.normcase(os.path.abspath(tempfile.gettempdir()))

    def _unlink_genlayer_temp(path, *args, **kwargs):
        try:
            _unlink(path, *args, **kwargs)
        except PermissionError:
            candidate = os.path.normcase(os.path.abspath(os.fspath(path)))
            if not candidate.startswith(_temp_root) or not os.path.basename(candidate).startswith(
                "tmp"
            ):
                raise

    os.unlink = _unlink_genlayer_temp


# RC5 direct mode has both legacy and current SDK module layouts. Patch only
# the test harness so the deployable contract remains unchanged.
try:
    # Keep extraction out of the shared user cache. The RC loader's Windows
    # tree replacement is susceptible to stale ACL/handle state there. Reuse
    # the already downloaded bundle but publish the extracted tree locally.
    from gltest.direct import sdk_loader as _sdk_loader

    _project_cache = Path(__file__).resolve().parents[1] / ".genlayer-cache"
    _sdk_loader.CACHE_DIR = _project_cache
    _sdk_loader.BUNDLE_CACHE_DIR = Path.home() / ".cache" / "gltest-direct" / "bundles-v2"
    _sdk_loader.TREE_CACHE_DIR = _project_cache / "trees-v2"
except ImportError:
    pass


try:
    from gltest.direct import loader as _direct_loader
    from gltest.direct import sdk_compat as _sdk_compat
    from gltest.direct import wasi_mock as _wasi_mock_compat

    def _import_calldata_rc():
        try:
            return importlib.import_module("genlayer.py.calldata")
        except ModuleNotFoundError:
            return importlib.import_module("genlayer.calldata")

    def _import_types_rc():
        try:
            return importlib.import_module("genlayer.py.types")
        except ModuleNotFoundError:
            return importlib.import_module("genlayer.types")

    _sdk_compat.import_calldata = _import_calldata_rc
    _sdk_compat.import_types = _import_types_rc
    _direct_loader.import_calldata = _import_calldata_rc
    _wasi_mock_compat.import_calldata = _import_calldata_rc

    _original_handle_llm_request = _wasi_mock_compat._handle_llm_request

    def _handle_llm_request_rc(vm, data):
        result = _original_handle_llm_request(vm, data)
        if isinstance(result, dict) and isinstance(result.get("ok"), dict):
            return {"ok": json.dumps(result["ok"], separators=(",", ":"))}
        return result

    _wasi_mock_compat._handle_llm_request = _handle_llm_request_rc

    # The direct loader reuses one SDK process across pytest cases, while the
    # RC SDK intentionally allows only one contract class per imported module.
    # Reset that loader-global registration between isolated deployments.
    _original_load_module = _direct_loader._load_module

    def _load_module_rc(contract_path):
        try:
            contract_module = importlib.import_module("genlayer.contract")
            contract_module.__known_contract__ = None
        except ModuleNotFoundError:
            pass
        return _original_load_module(contract_path)

    _direct_loader._load_module = _load_module_rc

    # Production consensus serializes the leader result before later state
    # code can mutate its local object. The direct adapter otherwise stores
    # the same dict by reference, which makes validator replay reject a
    # semantically valid result after auth metadata is appended.
    _original_patch_nondet = _direct_loader._patch_run_nondet_for_direct_mode

    def _patch_nondet_rc():
        _original_patch_nondet()
        vm_module = importlib.import_module("genlayer.vm")
        from gltest.direct import wasi_mock

        base_default = getattr(
            vm_module.run_nondet_default,
            "_rightsrail_base",
            vm_module.run_nondet_default,
        )
        base_regular = getattr(
            vm_module.run_nondet,
            "_rightsrail_base",
            vm_module.run_nondet,
        )

        def isolated_default(leader_fn, validator_fn, /, **kwargs):
            result = base_default(leader_fn, validator_fn, **kwargs)
            vm = wasi_mock.get_vm()
            stored, captured_leader, captured_validator = vm._captured_validators[-1]
            vm._captured_validators[-1] = (
                copy.deepcopy(stored),
                captured_leader,
                captured_validator,
            )
            return result

        def isolated_regular(leader_fn, validator_fn, /, **kwargs):
            result = base_regular(leader_fn, validator_fn, **kwargs)
            vm = wasi_mock.get_vm()
            stored, captured_leader, captured_validator = vm._captured_validators[-1]
            vm._captured_validators[-1] = (
                copy.deepcopy(stored),
                captured_leader,
                captured_validator,
            )
            return result

        isolated_default._rightsrail_base = base_default
        isolated_regular._rightsrail_base = base_regular
        vm_module.run_nondet_default = isolated_default
        vm_module.run_nondet = isolated_regular

    _direct_loader._patch_run_nondet_for_direct_mode = _patch_nondet_rc
except ImportError:
    pass


# Direct consensus is executed as a controlled local harness: leader output
# is returned and the validator closure is retained for an explicit test call.
try:
    from gltest.direct import wasi_mock as _wasi_mock

    try:
        _gl_vm = importlib.import_module("genlayer.gl.vm")
    except ModuleNotFoundError:
        _gl_vm = importlib.import_module("genlayer.vm")
    sys.modules["genlayer.vm"] = _gl_vm

    def _run_nondet_direct(leader_fn, validator_fn, /, **kwargs):
        result = leader_fn()
        _wasi_mock.get_vm()._captured_validators.append((result, leader_fn, validator_fn))
        return result

    _gl_vm.run_nondet_default = _run_nondet_direct
    _gl_vm.run_nondet = _run_nondet_direct
except ImportError:
    pass


# Keep direct VM sender/value cheatcodes aligned with the current RC module
# path and immutable gl.message snapshot.
try:
    from gltest.direct.vm import VMContext as _VMContext

    _original_refresh_gl_message = _VMContext._refresh_gl_message

    def _refresh_gl_message_rc(self):
        try:
            gl_module = importlib.import_module("genlayer.gl")
        except ModuleNotFoundError:
            try:
                gl_module = importlib.import_module("genlayer")
            except ModuleNotFoundError:
                return _original_refresh_gl_message(self)
        try:
            types_module = importlib.import_module("genlayer.py.types")
        except ModuleNotFoundError:
            types_module = importlib.import_module("genlayer.types")
        address_type = types_module.Address
        u256_type = types_module.u256

        def as_address(value):
            if isinstance(value, address_type):
                return value
            if isinstance(value, bytes):
                return address_type(value)
            if hasattr(value, "as_bytes"):
                return address_type(value.as_bytes)
            return value

        sender = as_address(self.sender)
        origin = as_address(self.origin)
        contract_address = as_address(self._contract_address)
        raw_source = getattr(gl_module, "message_raw", None)
        if raw_source is None:
            raw_source = gl_module.message.raw
        raw = dict(raw_source)
        raw.update(
            {
                "sender_address": sender,
                "origin_address": origin,
                "contract_address": contract_address,
                "value": self._value,
                "chain_id": self._chain_id,
                "datetime": self._datetime,
            }
        )
        gl_module.message_raw = raw
        gl_module.message.raw = raw
        gl_module.message.contract_address = contract_address
        gl_module.message.sender_address = sender
        gl_module.message.origin_address = origin
        gl_module.message.value = u256_type(self._value)
        gl_module.message.chain_id = u256_type(self._chain_id)

    _VMContext._refresh_gl_message = _refresh_gl_message_rc
except ImportError:
    pass


# The RC allocator does not always attach the generated storage descriptor.
# This is a test-only adapter for the installed gltest package.
try:
    from gltest.direct import loader as _direct_loader

    def _allocate_contract_rc(contract_cls, vm, *args, **kwargs):
        try:
            from genlayer.py.storage import ROOT_SLOT_ID
            from genlayer.py.storage._internal.generate import ORIGINAL_INIT_ATTR, _storage_build

            type_desc = _storage_build(contract_cls, {})
        except ModuleNotFoundError:
            from genlayer.storage import ROOT_SLOT_ID
            from genlayer.storage._internal.generate import (
                ORIGINAL_INIT_ATTR,
                _BuilderCtx,
                _storage_build,
            )

            type_desc = _storage_build(_BuilderCtx.empty(), contract_cls)

        slot = vm._storage.get_store_slot(ROOT_SLOT_ID)
        instance = type_desc.get(slot, 0)
        if not hasattr(instance, "__type_desc__"):
            instance.__type_desc__ = type_desc
        init_owner = getattr(type_desc, "cls", None)
        init = (
            getattr(init_owner, "__init__", None)
            if init_owner is not None
            else getattr(contract_cls, "__init__", None)
        )
        if init is not None and hasattr(init, ORIGINAL_INIT_ATTR):
            init = getattr(init, ORIGINAL_INIT_ATTR)
        if init is not None:
            init(instance, *args, **kwargs)
        return instance

    _direct_loader._allocate_contract = _allocate_contract_rc
except ImportError:
    pass
